public class Main {
    private static long workload(int limit) {
        long sum = 0;
        for (int i = 1; i <= limit; i++) sum += (long) i * i;
        return sum;
    }
    public static void main(String[] args) {
        for (int i = 0; i < 3; i++) workload(100_000); // warm-up only
        long start = System.nanoTime();
        long result = workload(1_000_000);
        long elapsed = System.nanoTime() - start;
        System.out.println("checksum=" + result + ", elapsedNs=" + elapsed);
    }
}
